    "tour.editor.title": "Take a tour",
    "tour.editor.firstVisit.title": "Take a tour",
    "tour.editor.firstVisit.desc": "A short walkthrough of Open, slides, the canvas, the toolbar, AI assistant, Present, and Output.",
    "tour.editor.firstVisit.skip": "Not now",
    "tour.editor.firstVisit.start": "Start",
    "tour.editor.step1.title": "Canvas",
    "tour.editor.step1.desc": "Displays the current slide. Select text or objects to edit; scroll or zoom ({mod}+scroll) to view the full page.",
    "tour.editor.step2.title": "Open",
    "tour.editor.step2.desc": "Open a .pptx from disk, create a presentation, restore from local cache, or open a file from online storage. You can also drop a file onto the window.",
    "tour.editor.stepSlides.title": "Slides",
    "tour.editor.stepSlides.desc": "Thumbnail list of the deck. Add, duplicate, or delete slides; click a thumbnail to switch.",
    "tour.editor.step3.title": "Toolbar",
    "tour.editor.step3.desc": "The top bar keeps Undo, Redo, and Share. The view bar below switches views, zoom, light or dark, and the properties panel, which shows Text, Appearance, Arrange, and Slide.",
    "tour.editor.stepAi.title": "AI assistant",
    "tour.editor.stepAi.desc": "Generate a presentation from a topic, or chat to edit the current deck. Capabilities, API settings, Skills, and MCP are in the same panel.",
    "tour.editor.step4.title": "Present",
    "tour.editor.step4.desc": "Click play in the view bar to present with the selected start. It begins from the first slide until you pick another start from the arrow; the button icon follows that choice. Animations and click sequence are preserved. More slideshow settings live in the Present group.",
    "tour.editor.step5.title": "Command groups",
